package com.autoops.workflow.entity;import jakarta.persistence.*;@Entity @Table(name="workflow_steps")@Inheritance(strategy=InheritanceType.JOINED)public abstract class WorkflowStep{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)protected Long id;@Column(name="workflow_id",nullable=false)protected Long workflowId;@Column(nullable=false)protected String name;protected String description;@Column(nullable=false)protected Integer position;@Column(name="requires_approval",nullable=false)protected boolean requiresApproval;@Column(name="success_next_step_id")protected Long successNextStepId;@Column(name="failure_next_step_id")protected Long failureNextStepId;public Long getId(){return id;}public Long getWorkflowId(){return workflowId;}public Long getSuccessNextStepId(){return successNextStepId;}public Long getFailureNextStepId(){return failureNextStepId;}}
